const item = $input.first();
const j = item.json;

const headers = j.headers || {};
const getHeader = (name) => {
  const key = Object.keys(headers).find(k => k.toLowerCase() === name.toLowerCase());
  return key ? headers[key] : '';
};

const from = j.From || j.from || getHeader('from') || '';
const subject = j.Subject || j.subject || getHeader('subject') || '';
const messageId = j.id || j.messageId || '';
const threadId = j.threadId || '';
const body = j.textPlain || j.text || j.body || j.snippet || '';

const lower = `${subject} ${body}`.toLowerCase();
const keywords = [
  'quotation',
  'quote',
  'meeting',
  'project',
  'website',
  'ecommerce',
  'e-commerce',
  'branding',
  'brand identity',
  'marketing',
  'seo',
  'social media',
  'software',
  'web application',
  'automation',
  'ui/ux',
  'design',
  'nuvio',
  'agency',
  'services',
  'service',
  'pricing',
  'price',
  'cost',
  'enquiry',
  'inquiry',
  'work with',
  'work together',
  'help with',
  'looking for',
  'interested in',
  'what do you',
  'what is',
  'what are',
  'how much',
  'can you',
  'portfolio'
];

const matchedKeywords = keywords.filter(k => lower.includes(k));
const automatedSender = /no[- ]?reply|mailer-daemon|postmaster|notifications?@|noreply@/i.test(from);
const automatedSubject = /unsubscribe|newsletter|delivery status|automatic reply|out of office|failed delivery|mail delivery/i.test(subject);

return [{
  json: {
    original: j,
    from,
    subject,
    body,
    messageId,
    threadId,
    matchedKeywords,
    hasRelevantKeyword: matchedKeywords.length > 0,
    automatedSender,
    automatedSubject,
    shouldAnalyse: matchedKeywords.length > 0 && !automatedSender && !automatedSubject,
    receivedAt: new Date().toISOString()
  }
}];

const input = $input.first().json;

const fallback = {
  decision: 'ESCALATE',
  reason: 'The AI response could not be safely parsed.',
  reply: 'Thank you for your enquiry. This requires confirmation from our team. I will recommend that a Nuvio Agency representative reviews your request so you can receive accurate information.',
  needsHuman: true
};

// The OpenAI node (jsonOutput) returns the parsed object under message.content.
let candidate = input.message && input.message.content;
if (candidate === undefined || candidate === null) {
  candidate = input.content || input.text || input.output || input.response || input;
}

let parsed;
if (candidate && typeof candidate === 'object') {
  parsed = candidate;
} else {
  let raw = typeof candidate === 'string' ? candidate : JSON.stringify(candidate || '');
  raw = raw.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    parsed = null;
  }
}

if (!parsed || typeof parsed !== 'object') parsed = { ...fallback };

const allowed = ['AUTO_REPLY', 'ESCALATE'];
if (!allowed.includes(parsed.decision)) parsed.decision = 'ESCALATE';
if (!parsed.reply || typeof parsed.reply !== 'string') {
  parsed.reply = fallback.reply;
}

return [{
  json: {
    ...$('Prepare Email').first().json,
    decision: parsed.decision,
    reason: parsed.reason || 'No reason supplied.',
    reply: parsed.reply,
    needsHuman: parsed.decision === 'ESCALATE'
  }
}];

